/**
 * Edapt CRM database schema (Postgres / Supabase).
 *
 * Conventions
 * - Every id is a uuid generated by Postgres.
 * - Money columns are numeric(14,2) read as JS numbers. INR is the base currency;
 *   every money row stores its own currency, the fx_rate used and the INR value,
 *   so past LTV never shifts when rates change.
 * - Dropdown values (channel, first door, campaign, industry, ...) are stored as
 *   stable keys; labels live in settings (see src/lib/settings/defaults.ts).
 * - A merged contact is never deleted: it keeps its row with merged_into_id set and
 *   all of its child rows are re-pointed to the surviving contact (see contact_merges).
 *   ALWAYS filter `merged_into_id IS NULL` when listing contacts (use contactScope()).
 */
import { sql } from "drizzle-orm";
import {
  bigserial,
  boolean,
  index,
  integer,
  jsonb,
  numeric,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const money = (name: string) => numeric(name, { precision: 14, scale: 2, mode: "number" });
const rate = (name: string) => numeric(name, { precision: 14, scale: 6, mode: "number" });
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });
const createdAt = () => ts("created_at").notNull().defaultNow();
const updatedAt = () => ts("updated_at").notNull().defaultNow();

// ---------------------------------------------------------------------------
// Shared value types
// ---------------------------------------------------------------------------

export const ROLES = ["admin", "manager", "sales", "support"] as const;
export type Role = (typeof ROLES)[number];

export const STAGES = [
  "new",
  "contacted",
  "qualified",
  "first_purchase",
  "repeat",
  "advocate",
  "dormant",
  "lost",
] as const;
export type Stage = (typeof STAGES)[number];
/** Stages a salesperson may set by hand. All others are set by the system. */
export const MANUAL_STAGES: Stage[] = ["qualified", "lost"];

export const CONTACT_TYPES = ["individual", "business"] as const;
export type ContactType = (typeof CONTACT_TYPES)[number];

export const ORG_KINDS = ["school", "constituency_office", "company", "partner"] as const;
export type OrgKind = (typeof ORG_KINDS)[number];

export const PAYMENT_MODES = ["tagmango", "bank_transfer", "upi_qr", "cash", "other"] as const;
export type PaymentMode = (typeof PAYMENT_MODES)[number];

export const PURCHASE_SOURCES = ["tagmango", "manual", "import"] as const;
export type PurchaseSource = (typeof PURCHASE_SOURCES)[number];

/** pending: nothing verified yet; partial: some instalments verified; paid: fully verified;
 *  refunded: fully refunded; cancelled: voided before any money arrived. */
export const PURCHASE_STATUSES = ["pending", "partial", "paid", "refunded", "cancelled"] as const;
export type PurchaseStatus = (typeof PURCHASE_STATUSES)[number];

export const PAYMENT_KINDS = ["payment", "refund"] as const;
export type PaymentKind = (typeof PAYMENT_KINDS)[number];

/** scheduled: a future instalment; unverified: money claimed (UTR/screenshot) but not checked;
 *  verified: counts toward LTV; rejected: verification failed. */
export const PAYMENT_STATUSES = ["scheduled", "unverified", "verified", "rejected"] as const;
export type PaymentStatus = (typeof PAYMENT_STATUSES)[number];

export const TASK_TYPES = [
  "follow_up",
  "abandoned_checkout",
  "hot_lead",
  "new_lead",
  "untouched_lead",
  "next_rung",
  "at_risk",
  "instalment_due",
  "unverified_payment",
  "new_advocate",
  "vip_quiet",
  "lead_released",
  "transfer_request",
  "duplicate_review",
] as const;
export type TaskType = (typeof TASK_TYPES)[number];

export const TASK_STATUSES = ["open", "done", "dismissed"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];

export const INTERACTION_TYPES = [
  "call",
  "whatsapp",
  "meeting",
  "email",
  "note",
  "support_issue",
] as const;
export type InteractionType = (typeof INTERACTION_TYPES)[number];

export const RATING_SOURCES = ["sales", "self", "import"] as const;
export type RatingSource = (typeof RATING_SOURCES)[number];

export const IMPORT_MATCH_RESULTS = ["new", "merge", "conflict", "invalid", "skip"] as const;
export type ImportMatchResult = (typeof IMPORT_MATCH_RESULTS)[number];

export const IMPORT_STATUSES = [
  "uploaded",
  "mapped",
  "cleaned",
  "matched",
  "committing",
  "committed",
  "undone",
  "failed",
] as const;
export type ImportStatus = (typeof IMPORT_STATUSES)[number];

/** Where a profile field's current value came from. Sales overrides self; self never overrides sales. */
export type FieldSource = "sales" | "self" | "system" | "import";

// ---------------------------------------------------------------------------
// Team
// ---------------------------------------------------------------------------

export const users = pgTable(
  "users",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    email: text("email").notNull(),
    passwordHash: text("password_hash"),
    role: text("role").$type<Role>().notNull().default("sales"),
    /** Team key from settings `teams` (e.g. "kerala", "dubai"). */
    team: text("team"),
    phone: text("phone"),
    timezone: text("timezone").notNull().default("Asia/Kolkata"),
    active: boolean("active").notNull().default(true),
    /** Round-robin cursor: the least recently assigned active salesperson gets the next lead. */
    lastAssignedAt: ts("last_assigned_at"),
    lastLoginAt: ts("last_login_at"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("users_email_uq").on(sql`lower(${t.email})`)],
);

export const sessions = pgTable(
  "sessions",
  {
    /** sha256 of the cookie token; the raw token is never stored. */
    id: text("id").primaryKey(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    expiresAt: ts("expires_at").notNull(),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [index("sessions_user_idx").on(t.userId)],
);

// ---------------------------------------------------------------------------
// People and accounts
// ---------------------------------------------------------------------------

export const organisations = pgTable(
  "organisations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    kind: text("kind").$type<OrgKind>().notNull().default("company"),
    city: text("city"),
    state: text("state"),
    /** ISO 3166-1 alpha-2 */
    country: text("country"),
    phone: text("phone"),
    notes: text("notes"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("organisations_name_idx").on(sql`lower(${t.name})`)],
);

export const contacts = pgTable(
  "contacts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** Identity key. E.164, e.g. +919876543210 */
    phoneE164: text("phone_e164").notNull(),
    /** ISO country of the phone number, e.g. IN, AE */
    phoneCountry: text("phone_country"),
    name: text("name").notNull(),
    email: text("email"),
    altPhones: text("alt_phones").array().notNull().default(sql`'{}'::text[]`),
    altEmails: text("alt_emails").array().notNull().default(sql`'{}'::text[]`),
    type: text("type").$type<ContactType>().notNull().default("individual"),
    organisationId: uuid("organisation_id").references(() => organisations.id, {
      onDelete: "set null",
    }),
    city: text("city"),
    state: text("state"),
    /** ISO 3166-1 alpha-2 */
    country: text("country"),
    /** language key from settings lists.languages */
    language: text("language"),
    /** age band key, e.g. "35-44" */
    ageBand: text("age_band"),
    /** industry key from settings lists.industries */
    industry: text("industry"),
    designation: text("designation"),
    companyName: text("company_name"),
    /** 1..5 */
    spendingBand: integer("spending_band"),
    /** 0..5 */
    aiLevel: integer("ai_level"),
    /** 0..5 */
    umerLevel: integer("umer_level"),
    /** 1..5 */
    gutStars: integer("gut_stars"),
    /** Where each rated/profile field's current value came from: { ai_level: "self", ... } */
    fieldSources: jsonb("field_sources").$type<Record<string, FieldSource>>().notNull().default({}),
    salesNotes: text("sales_notes"),
    /** first door key. Set once, never overwritten (except by merge keeping the oldest). */
    firstDoor: text("first_door").notNull(),
    firstCampaign: text("first_campaign"),
    firstChannel: text("first_channel"),
    lastChannel: text("last_channel"),
    lastCampaign: text("last_campaign"),
    referredById: uuid("referred_by_id"),
    consent: boolean("consent"),
    consentAt: ts("consent_at"),
    stage: text("stage").$type<Stage>().notNull().default("new"),
    lostReason: text("lost_reason"),
    stageChangedAt: ts("stage_changed_at").notNull().defaultNow(),
    ownerId: uuid("owner_id").references(() => users.id, { onDelete: "set null" }),
    firstOwnerId: uuid("first_owner_id").references(() => users.id, { onDelete: "set null" }),
    ownerAssignedAt: ts("owner_assigned_at"),
    tags: text("tags").array().notNull().default(sql`'{}'::text[]`),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),

    // --- activity markers (maintained by services) ---
    lastEnquiryAt: ts("last_enquiry_at"),
    lastInteractionAt: ts("last_interaction_at"),
    /** max(enquiry, interaction, purchase) — drives Readiness "recent interest" */
    lastActivityAt: ts("last_activity_at"),

    // --- calculated, read-only (see src/lib/metrics) ---
    ltvInr: money("ltv_inr").notNull().default(0),
    purchaseCount: integer("purchase_count").notNull().default(0),
    familyCount: integer("family_count").notNull().default(0),
    families: text("families").array().notNull().default(sql`'{}'::text[]`),
    /** highest ladder rung bought (0 = none) */
    currentRung: integer("current_rung").notNull().default(0),
    firstPurchaseAt: ts("first_purchase_at"),
    lastPurchaseAt: ts("last_purchase_at"),
    firstFamily: text("first_family"),
    avgGapDays: numeric("avg_gap_days", { precision: 10, scale: 2, mode: "number" }),
    nextExpectedAt: ts("next_expected_at"),
    atRisk: boolean("at_risk").notNull().default(false),
    repeatProb90d: numeric("repeat_prob_90d", { precision: 6, scale: 4, mode: "number" }),
    expected90dInr: money("expected_90d_inr"),
    nextOffer: text("next_offer"),
    nextOfferProductId: uuid("next_offer_product_id"),
    fit: integer("fit"),
    readiness: integer("readiness"),
    /** null for leads (value is not used until someone pays) */
    value: integer("value"),
    edaptScore: integer("edapt_score"),
    grade: text("grade").$type<"A" | "B" | "C" | "D">(),
    networkValueInr: money("network_value_inr").notNull().default(0),
    /** number of referred contacts who have paid */
    referralCount: integer("referral_count").notNull().default(0),
    scoredAt: ts("scored_at"),

    // --- merge bookkeeping ---
    mergedIntoId: uuid("merged_into_id"),
    mergedAt: ts("merged_at"),

    /** id of the import batch that created this contact, for one-click undo */
    importBatchId: uuid("import_batch_id"),

    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("contacts_phone_uq").on(t.phoneE164),
    index("contacts_email_idx").on(sql`lower(${t.email})`),
    index("contacts_alt_phones_idx").using("gin", t.altPhones),
    index("contacts_alt_emails_idx").using("gin", t.altEmails),
    index("contacts_tags_idx").using("gin", t.tags),
    index("contacts_owner_idx").on(t.ownerId),
    index("contacts_stage_idx").on(t.stage),
    index("contacts_grade_idx").on(t.grade),
    index("contacts_first_door_idx").on(t.firstDoor),
    index("contacts_referred_by_idx").on(t.referredById),
    index("contacts_name_idx").on(sql`lower(${t.name})`),
    index("contacts_merged_idx").on(t.mergedIntoId),
    // people of a B2B account (organisation pages, people counts)
    index("contacts_org_idx").on(t.organisationId),
    // recent assignments: the untouched-lead alert (every 15 minutes) and the daily digest's new leads
    index("contacts_owner_assigned_idx").on(t.ownerAssignedAt),
  ],
);

/** Every inbound touch: a chat, a form fill, a checkout start, an imported row, a quick add. */
export const enquiries = pgTable(
  "enquiries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    /** channel key */
    channel: text("channel").notNull(),
    /** campaign key */
    campaign: text("campaign"),
    productInterest: text("product_interest"),
    /** Idempotency key from the source system (e.g. "libromi:msg:123", "meta:lead:456"). */
    sourceRef: text("source_ref"),
    rawPayload: jsonb("raw_payload"),
    receivedAt: ts("received_at").notNull().defaultNow(),
    /** open | handled | checkout_started | checkout_failed | recovered | abandoned */
    status: text("status").notNull().default("open"),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    notes: text("notes"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("enquiries_source_ref_uq").on(t.sourceRef),
    index("enquiries_contact_idx").on(t.contactId, t.receivedAt),
    index("enquiries_channel_idx").on(t.channel, t.receivedAt),
    index("enquiries_status_idx").on(t.status),
  ],
);

export const interactions = pgTable(
  "interactions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    /** null when the system logged it (e.g. an inbound WhatsApp reply) */
    userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
    type: text("type").$type<InteractionType>().notNull(),
    /** "in" | "out" */
    direction: text("direction").notNull().default("out"),
    /** outcome key from settings lists.outcomes */
    outcome: text("outcome"),
    summary: text("summary"),
    nextFollowUpAt: ts("next_follow_up_at"),
    occurredAt: ts("occurred_at").notNull().defaultNow(),
    /** idempotency key for interactions created by webhooks */
    externalRef: text("external_ref"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("interactions_external_ref_uq").on(t.externalRef),
    index("interactions_contact_idx").on(t.contactId, t.occurredAt),
    index("interactions_user_idx").on(t.userId, t.occurredAt),
  ],
);

/** Rating history. The contact row holds the latest values. */
export const ratings = pgTable(
  "ratings",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    ratedByUserId: uuid("rated_by_user_id").references(() => users.id, { onDelete: "set null" }),
    source: text("source").$type<RatingSource>().notNull().default("sales"),
    aiLevel: integer("ai_level"),
    umerLevel: integer("umer_level"),
    spendingBand: integer("spending_band"),
    gutStars: integer("gut_stars"),
    ageBand: text("age_band"),
    industry: text("industry"),
    notes: text("notes"),
    createdAt: createdAt(),
  },
  (t) => [index("ratings_contact_idx").on(t.contactId, t.createdAt)],
);

// ---------------------------------------------------------------------------
// Catalogue and money
// ---------------------------------------------------------------------------

export const products = pgTable(
  "products",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    /** product family key from settings ladder.families */
    family: text("family").notNull(),
    /** ladder rung (1..4); null for side groups such as B2B or delegation */
    rung: integer("rung"),
    listPrice: money("list_price").notNull().default(0),
    currency: text("currency").notNull().default("INR"),
    active: boolean("active").notNull().default(true),
    /** TagMango mango/product ids or name patterns that map to this product */
    externalIds: text("external_ids").array().notNull().default(sql`'{}'::text[]`),
    description: text("description"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index("products_family_idx").on(t.family)],
);

export const purchases = pgTable(
  "purchases",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** For B2B deals this is the person who signed. */
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    organisationId: uuid("organisation_id").references(() => organisations.id, {
      onDelete: "set null",
    }),
    productId: uuid("product_id").references(() => products.id, { onDelete: "set null" }),
    /** product name at the time of sale (products can be renamed) */
    productName: text("product_name").notNull(),
    /** product family at the time of sale */
    family: text("family").notNull(),
    listPrice: money("list_price"),
    discount: money("discount").notNull().default(0),
    /** final agreed amount in `currency` */
    amount: money("amount").notNull(),
    currency: text("currency").notNull().default("INR"),
    fxRate: rate("fx_rate").notNull().default(1),
    amountInr: money("amount_inr").notNull(),
    purchasedAt: ts("purchased_at").notNull().defaultNow(),
    mode: text("mode").$type<PaymentMode>().notNull(),
    /** TagMango order id or UTR. Unique so nothing is counted twice. */
    reference: text("reference"),
    status: text("status").$type<PurchaseStatus>().notNull().default("pending"),
    /** null = self-serve */
    creditedUserId: uuid("credited_user_id").references(() => users.id, { onDelete: "set null" }),
    assisted: boolean("assisted").notNull().default(false),
    creditAdjustedById: uuid("credit_adjusted_by_id").references(() => users.id, {
      onDelete: "set null",
    }),
    source: text("source").$type<PurchaseSource>().notNull().default("manual"),
    /** true when there is an instalment (EMI) schedule */
    hasInstalments: boolean("has_instalments").notNull().default(false),
    proofUrl: text("proof_url"),
    notes: text("notes"),
    /** affiliate / campaign info carried on the order */
    campaign: text("campaign"),
    rawPayload: jsonb("raw_payload"),
    importBatchId: uuid("import_batch_id"),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("purchases_reference_uq").on(t.reference),
    index("purchases_contact_idx").on(t.contactId, t.purchasedAt),
    index("purchases_org_idx").on(t.organisationId),
    index("purchases_purchased_at_idx").on(t.purchasedAt),
    index("purchases_credited_idx").on(t.creditedUserId),
  ],
);

/** Instalments, one-off payments and refunds. LTV = verified payments - verified refunds (INR). */
export const payments = pgTable(
  "payments",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    purchaseId: uuid("purchase_id")
      .notNull()
      .references(() => purchases.id, { onDelete: "cascade" }),
    /** denormalised for fast LTV queries; kept in sync on merge */
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    kind: text("kind").$type<PaymentKind>().notNull().default("payment"),
    /** instalment number, 1-based */
    seq: integer("seq").notNull().default(1),
    /** always positive; a refund is identified by kind */
    amount: money("amount").notNull(),
    currency: text("currency").notNull().default("INR"),
    fxRate: rate("fx_rate").notNull().default(1),
    amountInr: money("amount_inr").notNull(),
    dueAt: ts("due_at"),
    paidAt: ts("paid_at"),
    mode: text("mode").$type<PaymentMode>(),
    /** UTR / TagMango order id / refund id. Unique when present. */
    reference: text("reference"),
    status: text("status").$type<PaymentStatus>().notNull().default("unverified"),
    verifiedById: uuid("verified_by_id").references(() => users.id, { onDelete: "set null" }),
    verifiedAt: ts("verified_at"),
    proofUrl: text("proof_url"),
    /** refund reason or rejection note */
    reason: text("reason"),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("payments_reference_uq").on(t.reference),
    index("payments_purchase_idx").on(t.purchaseId),
    index("payments_contact_idx").on(t.contactId),
    index("payments_status_idx").on(t.status, t.dueAt),
  ],
);

// ---------------------------------------------------------------------------
// Ownership, work and alerts
// ---------------------------------------------------------------------------

export const ownershipLog = pgTable(
  "ownership_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    contactId: uuid("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    fromUserId: uuid("from_user_id").references(() => users.id, { onDelete: "set null" }),
    toUserId: uuid("to_user_id").references(() => users.id, { onDelete: "set null" }),
    reason: text("reason").notNull(),
    /** null = the system */
    changedById: uuid("changed_by_id").references(() => users.id, { onDelete: "set null" }),
    changedAt: ts("changed_at").notNull().defaultNow(),
  },
  (t) => [index("ownership_log_contact_idx").on(t.contactId, t.changedAt)],
);

/** Follow-ups and alerts. Everything on the Today queue is a task. */
export const tasks = pgTable(
  "tasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    contactId: uuid("contact_id").references(() => contacts.id, { onDelete: "cascade" }),
    /** null = the unassigned pool */
    userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
    type: text("type").$type<TaskType>().notNull(),
    /** human-readable "why it is here" shown on every Today row */
    reason: text("reason").notNull(),
    dueAt: ts("due_at").notNull().defaultNow(),
    status: text("status").$type<TaskStatus>().notNull().default("open"),
    /** higher sorts first within its band */
    priority: integer("priority").notNull().default(0),
    /** prevents the same alert being raised twice, e.g. "at_risk:<contact>:<yyyy-mm>" */
    dedupeKey: text("dedupe_key"),
    payload: jsonb("payload").$type<Record<string, unknown>>(),
    createdById: uuid("created_by_id").references(() => users.id, { onDelete: "set null" }),
    completedById: uuid("completed_by_id").references(() => users.id, { onDelete: "set null" }),
    completedAt: ts("completed_at"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("tasks_dedupe_uq").on(t.dedupeKey),
    index("tasks_user_status_idx").on(t.userId, t.status, t.dueAt),
    index("tasks_contact_idx").on(t.contactId),
    // open tasks of one type (alert rules run every 15 minutes: follow-up pings, untouched-lead cleanup)
    index("tasks_open_type_due_idx").on(t.type, t.dueAt).where(sql`${t.status} = 'open'`),
  ],
);

/** In-app alerts (the bell). Email copies are tracked with emailed_at. */
export const notifications = pgTable(
  "notifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    type: text("type").notNull(),
    title: text("title").notNull(),
    body: text("body"),
    contactId: uuid("contact_id").references(() => contacts.id, { onDelete: "cascade" }),
    taskId: uuid("task_id").references(() => tasks.id, { onDelete: "cascade" }),
    /** also send by email (hot lead, unverified payment, ...) */
    email: boolean("email").notNull().default(false),
    emailedAt: ts("emailed_at"),
    readAt: ts("read_at"),
    dedupeKey: text("dedupe_key"),
    createdAt: createdAt(),
  },
  (t) => [
    index("notifications_user_idx").on(t.userId, t.readAt, t.createdAt),
    index("notifications_contact_idx").on(t.contactId),
    uniqueIndex("notifications_dedupe_uq").on(t.dedupeKey),
    // alerts waiting for their email copy (tiny: rows leave it once emailed)
    index("notifications_email_pending_idx").on(t.createdAt).where(sql`${t.email} and ${t.emailedAt} is null`),
  ],
);

// ---------------------------------------------------------------------------
// Data quality
// ---------------------------------------------------------------------------

export const contactMerges = pgTable(
  "contact_merges",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    winnerId: uuid("winner_id")
      .notNull()
      .references(() => contacts.id),
    loserId: uuid("loser_id")
      .notNull()
      .references(() => contacts.id),
    /** ids of every child row re-pointed from loser to winner, per table, for undo */
    moved: jsonb("moved").$type<Record<string, string[]>>().notNull(),
    /** winner's columns before the merge, for undo */
    winnerBefore: jsonb("winner_before").$type<Record<string, unknown>>().notNull(),
    reason: text("reason"),
    mergedById: uuid("merged_by_id").references(() => users.id, { onDelete: "set null" }),
    mergedAt: ts("merged_at").notNull().defaultNow(),
    undoneAt: ts("undone_at"),
    undoneById: uuid("undone_by_id").references(() => users.id, { onDelete: "set null" }),
  },
  (t) => [index("contact_merges_winner_idx").on(t.winnerId), index("contact_merges_loser_idx").on(t.loserId)],
);

/** Possible duplicates (e.g. same name in the same city) waiting for a human. Never auto-merged. */
export const duplicateReviews = pgTable(
  "duplicate_reviews",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    contactAId: uuid("contact_a_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    contactBId: uuid("contact_b_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    reason: text("reason").notNull(),
    /** open | merged | dismissed */
    status: text("status").notNull().default("open"),
    resolvedById: uuid("resolved_by_id").references(() => users.id, { onDelete: "set null" }),
    resolvedAt: ts("resolved_at"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("duplicate_reviews_pair_uq").on(t.contactAId, t.contactBId),
    index("duplicate_reviews_status_idx").on(t.status),
  ],
);

// ---------------------------------------------------------------------------
// Imports
// ---------------------------------------------------------------------------

export const importBatches = pgTable("import_batches", {
  id: uuid("id").primaryKey().defaultRandom(),
  fileName: text("file_name").notNull(),
  /** tagmango | zoho | delegation | program_sheet | other */
  source: text("source").notNull(),
  uploadedById: uuid("uploaded_by_id").references(() => users.id, { onDelete: "set null" }),
  status: text("status").$type<ImportStatus>().notNull().default("uploaded"),
  /** { total, new, merge, conflict, invalid, skip, created, merged, purchases } */
  counts: jsonb("counts").$type<Record<string, number>>().notNull().default({}),
  /** source column -> target field */
  mapping: jsonb("mapping").$type<Record<string, string>>(),
  /** defaults applied to every row: first door, channel, campaign, tags, owner */
  defaults: jsonb("defaults").$type<Record<string, unknown>>().notNull().default({}),
  fileUrl: text("file_url"),
  error: text("error"),
  createdAt: createdAt(),
  committedAt: ts("committed_at"),
  undoneAt: ts("undone_at"),
  undoneById: uuid("undone_by_id").references(() => users.id, { onDelete: "set null" }),
});

export const importRows = pgTable(
  "import_rows",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    batchId: uuid("batch_id")
      .notNull()
      .references(() => importBatches.id, { onDelete: "cascade" }),
    rowNumber: integer("row_number").notNull(),
    /** the original row, never modified */
    raw: jsonb("raw").$type<Record<string, unknown>>().notNull(),
    /** after column mapping */
    mapped: jsonb("mapped").$type<Record<string, unknown>>(),
    /** after cleaning (normalised phone, proper-case name, parsed dates/amounts) */
    cleaned: jsonb("cleaned").$type<Record<string, unknown>>(),
    matchResult: text("match_result").$type<ImportMatchResult>(),
    matchContactId: uuid("match_contact_id"),
    issues: jsonb("issues").$type<string[]>().notNull().default([]),
    /** create | merge | skip — the reviewer's decision (defaults from match_result) */
    resolution: text("resolution"),
    /** resulting contact after commit */
    contactId: uuid("contact_id"),
    /** what commit changed, for undo: { createdContact, updatedFields, purchaseIds, ... } */
    applied: jsonb("applied").$type<Record<string, unknown>>(),
    createdAt: createdAt(),
  },
  (t) => [
    index("import_rows_batch_idx").on(t.batchId, t.rowNumber),
    index("import_rows_match_idx").on(t.batchId, t.matchResult),
  ],
);

// ---------------------------------------------------------------------------
// Configuration, audit, integrations
// ---------------------------------------------------------------------------

export const settings = pgTable("settings", {
  key: text("key").primaryKey(),
  value: jsonb("value").notNull(),
  updatedById: uuid("updated_by_id").references(() => users.id, { onDelete: "set null" }),
  updatedAt: updatedAt(),
});

export const auditLog = pgTable(
  "audit_log",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    tableName: text("table_name").notNull(),
    rowId: text("row_id"),
    /** insert | update | delete | merge | unmerge | export | login | verify | reassign | import | undo */
    action: text("action").notNull().default("update"),
    field: text("field"),
    oldValue: jsonb("old_value"),
    newValue: jsonb("new_value"),
    userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
    changedAt: ts("changed_at").notNull().defaultNow(),
  },
  (t) => [
    index("audit_log_row_idx").on(t.tableName, t.rowId),
    index("audit_log_changed_idx").on(t.changedAt),
    // Settings > Audit log, newest first: "who changed what" and the export log (exports, refused exports)
    index("audit_log_user_idx").on(t.userId, t.id),
    index("audit_log_action_idx").on(t.action, t.id),
  ],
);

/** Raw inbound webhook deliveries, for idempotency and debugging. */
export const webhookEvents = pgTable(
  "webhook_events",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** tagmango | libromi | pabbly_meta | pabbly_website | ... */
    source: text("source").notNull(),
    /** unique per source event, e.g. "tagmango:order:123:completed" */
    eventKey: text("event_key").notNull(),
    payload: jsonb("payload").notNull(),
    receivedAt: ts("received_at").notNull().defaultNow(),
    processedAt: ts("processed_at"),
    error: text("error"),
    contactId: uuid("contact_id"),
  },
  (t) => [
    uniqueIndex("webhook_events_key_uq").on(t.eventKey),
    index("webhook_events_source_idx").on(t.source, t.receivedAt),
    // the newest-first event log in Settings > Integrations
    index("webhook_events_received_idx").on(t.receivedAt),
  ],
);

/** Saved filters on the Contacts list. */
export const savedViews = pgTable("saved_views", {
  id: uuid("id").primaryKey().defaultRandom(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  name: text("name").notNull(),
  /** the contacts list query string, e.g. "grade=A&stage=new" */
  query: text("query").notNull(),
  shared: boolean("shared").notNull().default(false),
  createdAt: createdAt(),
});

export type User = typeof users.$inferSelect;
export type Contact = typeof contacts.$inferSelect;
export type NewContact = typeof contacts.$inferInsert;
export type Organisation = typeof organisations.$inferSelect;
export type Enquiry = typeof enquiries.$inferSelect;
export type Interaction = typeof interactions.$inferSelect;
export type Rating = typeof ratings.$inferSelect;
export type Product = typeof products.$inferSelect;
export type Purchase = typeof purchases.$inferSelect;
export type Payment = typeof payments.$inferSelect;
export type Task = typeof tasks.$inferSelect;
export type Notification = typeof notifications.$inferSelect;
export type ImportBatch = typeof importBatches.$inferSelect;
export type ImportRow = typeof importRows.$inferSelect;
